cat > src/list.sh <<'EOF'
#!/bin/bash
# list.sh [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
if [ -n "${1:-}" ] && ! [[ "$1" =~ ^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$ ]]; then echo "bad date: $1 (expected YYYY-MM-DD)" >&2; exit 2; fi
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="${1:-}" 'NF && (d == "" || $2 == d) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort
EOF
cat > src/remind.sh <<'EOF'
#!/bin/bash
# remind.sh DATE: one reminder per booking of the day, from the listing (remind.sh and list.sh both check DATE).
set -u
if [ -n "${1:-}" ] && ! [[ "$1" =~ ^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$ ]]; then echo "bad date: $1 (expected YYYY-MM-DD)" >&2; exit 2; fi
out=$(bash "$(dirname "$0")/list.sh" "$@") || exit $?
[ -z "$out" ] || printf '%s\n' "$out" | while read -r d t r w; do echo "reminder to $w: $r $d $t"; done
EOF
cat > spec/list_date.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\n' > "$t"
printf 'aoi\t2026-01-05\t09:00\t10:30\tx\n' >> "$t"
BOOKINGS=$t bash src/list.sh 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026/01/01 2>&1 >/dev/null)" = 'bad date: 2026/01/01 (expected YYYY-MM-DD)' ] || { echo "bad date message"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-13-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "month 13 should exit 2"; fail=1; }
BOOKINGS=$t bash src/remind.sh 2026/01/05 >/dev/null 2>&1; [ $? = 2 ] || { echo "remind: a malformed date should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh 2026/01/05 2>&1 >/dev/null)" = 'bad date: 2026/01/05 (expected YYYY-MM-DD)' ] || { echo "remind: bad date message"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-01-05 >/dev/null 2>&1; [ $? = 0 ] || { echo "a well-formed date should exit 0"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026-01-05)" = '2026-01-05 09:00-10:30 aoi x' ] || { echo "a well-formed date should list its bookings"; fail=1; }
BOOKINGS=$t bash src/remind.sh 2026-01-05 | grep -q '^reminder to x: aoi 2026-01-05 09:00$' || { echo "remind: a well-formed date should remind"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash tools/check; echo "check rc=$?"; bash tools/lint; echo "lint rc=$?"; bash -c 'out=$(bash src/list.sh 2026-02-30 2>&1); echo "$out"'

